<template><StoryPlayer :story="story" :loading="loading" /></template><script setup lang="ts">const api=useApi();const route=useRoute();const router=useRouter();const loading=ref(true);const story=ref<any>();function redirectNotFound(){void router.replace({path:'/404',query:{from:route.fullPath}})}onMounted(async()=>{try{story.value=await api.get(`/stories/${route.params.slug}`);if(!story.value)redirectNotFound()}catch(error:any){story.value=null;if(error?.status===404)redirectNotFound()}finally{loading.value=false}})</script>
